// Галерея страницы объявления /businessdetail (#d31f3b, PR #204 — заменяет #c49537): фиксированное широкое окно
// `aspect-video max-h-[400px]` (десктоп 800×400, телефон 16:9 во всю ширину), картинка object-fit cover 50% 50%;
// клик по окну (кнопка-слой «הצגת התמונה במסך מלא») открывает лайтбокс role=dialog на чёрном фоне.
// Прод — только просмотр: не-GET запросы блокируются (кроме RPC-чтения), SW выключен в spec (test.use).
// Окно галереи не имеет роли/подписи — ищется по вёрстке (WINDOW_CSS ниже).
import { expect, Page, test } from '@playwright/test';

export const LOAD = { timeout: 20_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const WRITE_RPC = /increment|track|insert|update|delete|create|upsert|add_|remove|set_|toggle|log/i;
/** Допуски: пропорция окна ±2 %, картинка = окну ±1 px, размер окна vs замер QA ±2 px. */
export const RATIO_TOL = 0.02;
export const PX_TOL = 1;
export const SIZE_TOL = 2;
/** Фиксированное окно (#d31f3b, замер QA 2026-11-10): десктоп 800×400; телефон — 16:9 во всю ширину контента (< 400). */
export const DESKTOP_FRAME = { w: 800, h: 400 };

export const LISTINGS = {
  /** «עסק של תפאורות מתנפחות ענקיות לאירועים», первая картинка 1122×1402 */
  vertical: { id: '7c541b48-464c-4eb7-a2f0-e8476f592c9d', nat: [1122, 1402] as [number, number] },
  /** «מינימרקט פעיל ורווחי», первая картинка 1254×1254 */
  square: { id: 'fbc426a0-354b-4336-82bf-1a3276c655b4', nat: [1254, 1254] as [number, number] },
  /** «משתלה», 4 картинки разных пропорций */
  mixed: { id: '35c34e3d-68f8-4cb7-9e0b-e82ad5b46feb', count: 4 },
  /** «מסעדת בשרים למכירה», слайд 1 — видео, слайд 2 — единственная картинка (в лайтбоксе «1/1», без стрелок) */
  video: { id: 'df45628f-3a34-44ca-9331-fc2ec332dc2f' },
};

export type Shot = {
  win: { w: number; h: number; aspect: string };
  img: { src: string; alt: string; fit: string; pos: string; complete: boolean; opacity: number; nat: [number, number]; w: number; h: number } | null;
  video: { w: number; h: number } | null;
  transforms: string[]; // transform окна и текущей медиа
  vh: number;
  scrollY: number;
};

/**
 * Окно галереи. После PR #204 (#d31f3b) и для картинки, и для видео — один и тот же
 * `div.aspect-video.max-h-[400px].bg-stone-100.overflow-hidden` с прямым <img class="object-cover"> (во время перехода
 * их может быть 2: старая opacity 1 и новая opacity 0, complete=false) или прямым <video>; на слайде с картинкой поверх
 * лежит кнопка-слой «הצגת התמונה במסך מלא». Карточки «עסקים דומים» — bg-stone-50, не совпадают.
 */
export const WINDOW_CSS = 'div.bg-stone-100.overflow-hidden:has(> img), div.bg-stone-100.overflow-hidden:has(> video)';
export const windowLocator = (page: Page) => page.locator(WINDOW_CSS).first();

/** Блок записи и автозакрытие попапов (cookie — «חיוניים בלבד», PWA — «אולי מאוחר יותר»). До первого перехода. */
export async function prepare(page: Page) {
  await page.context().route('**/*', (route) => {
    const r = route.request();
    if (SAFE_METHODS.includes(r.method())) return route.fallback();
    const rpc = r.url().split('?')[0].match(/\/rest\/v1\/rpc\/([^/]+)$/);
    if (rpc && !WRITE_RPC.test(rpc[1])) return route.fallback();
    return route.abort('blockedbyclient');
  });
  // PWA-окно «אל תחמיצו אף הזדמנות» (iPhone) всплывает через 3 с после выбора cookie посреди листания: модалка
  // блокирует прокрутку (scrollY → 0) и прячет стрелки из дерева доступности. Закрываем его заранее —
  // состояние «אולי מאוחר יותר» нажата (снуз b4s_install_prompt_dismissed_at = сейчас, #631293); обработчик — запасной.
  // Cookie-баннер: выбор «חיוניים בלבד» сохраняется заранее (cookie-consent-v2, как в других хелперах) — на WebKit под
  // параллельной нагрузкой клик обработчика по анимирующемуся баннеру зависал до таймаута теста.
  await page.addInitScript(() => {
    try {
      localStorage.setItem('b4s_install_prompt_dismissed_at', String(Date.now()));
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem('cookie-consent-v2', JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }));
      }
    } catch {}
  });
  await page.addLocatorHandler(page.getByText('חיוניים בלבד', { exact: true }), (l) => l.click());
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (l) => l.click());
}

/** Открыть объявление. Объявление снято/не найдено — test.skip (данные прода), а не падение. */
export async function openListing(page: Page, id: string) {
  await page.goto(`/businessdetail?id=${id}`);
  const gallery = windowLocator(page);
  const notFound = page.getByText(/לא נמצא|לא קיים|אינו זמין|הוסר/).first();
  await expect(gallery.or(notFound), `объявление ${id.slice(0, 8)} открылось`).toBeVisible(LOAD);
  test.skip(!(await gallery.isVisible()), `объявление ${id} недоступно на проде (данные изменились)`);
}

/** Снимок окна галереи: размер, inline aspect-ratio, видимая картинка/видео, transform. */
export async function readWindow(page: Page): Promise<Shot> {
  return windowLocator(page).evaluate((win: HTMLElement) => {
    const r = win.getBoundingClientRect();
    // «Текущая медиа» = видимая (opacity > 0.05) загруженная картинка — при переходе из двух берём более непрозрачную
    // (при равенстве — бо́льшую); незагруженная новая (opacity 0, complete=false) не считается.
    const op = (e: Element) => parseFloat(getComputedStyle(e).opacity);
    const imgs = ([...win.querySelectorAll(':scope > img')] as HTMLImageElement[]).filter((i) => {
      const b = i.getBoundingClientRect();
      return op(i) > 0.05 && getComputedStyle(i).visibility !== 'hidden' && i.complete && i.naturalWidth > 0 && b.width > 0 && b.height > 0;
    });
    const area = (e: Element) => e.getBoundingClientRect().width * e.getBoundingClientRect().height;
    imgs.sort((a, b) => op(b) - op(a) || area(b) - area(a));
    const img = imgs[0];
    const media = (img || win.querySelector(':scope > video')) as HTMLElement | null;
    const v = win.querySelector(':scope > video');
    const transforms: string[] = [getComputedStyle(win).transform];
    if (media) transforms.push(getComputedStyle(media).transform);
    return {
      win: { w: r.width, h: r.height, aspect: win.style.aspectRatio },
      img: img
        ? {
            src: img.currentSrc || img.src,
            alt: img.alt,
            fit: getComputedStyle(img).objectFit,
            pos: getComputedStyle(img).objectPosition,
            complete: img.complete,
            opacity: op(img),
            nat: [img.naturalWidth, img.naturalHeight] as [number, number],
            w: img.getBoundingClientRect().width,
            h: img.getBoundingClientRect().height,
          }
        : null,
      video: v ? { w: v.getBoundingClientRect().width, h: v.getBoundingClientRect().height } : null,
      transforms,
      vh: window.innerHeight,
      scrollY: window.scrollY,
    };
  });
}

const ready = (s: Shot, prevSrc?: string) =>
  !!s.img && s.img.complete && s.img.nat[0] > 0 && s.img.opacity >= 0.99 && s.transforms.every((t) => t === 'none') && (!prevSrc || s.img.src !== prevSrc);
/** Нарисованная картинка не совпадает с окном (px) — 0, если элемент img на всё окно. */
const fillGap = (s: Shot) => Math.max(Math.abs(s.img!.w - s.win.w), Math.abs(s.img!.h - s.win.h));

/**
 * Дождаться картинки (complete, opacity 1, анимация закончилась, при листании — новый src) и того, что элемент img
 * занимает всё окно (±1 px). Окно фиксированное (#d31f3b) — ждём только загрузку/анимацию, не подстройку размера.
 */
export async function settledImage(page: Page, label: string, prevSrc?: string): Promise<Shot> {
  await expect
    .poll(async () => {
      const s = await readWindow(page);
      return ready(s, prevSrc) ? fillGap(s) : Number.POSITIVE_INFINITY;
    }, { ...LOAD, message: `${label}: картинка загрузилась, анимация закончилась, картинка на всё окно ±1 px` })
    .toBeLessThanOrEqual(PX_TOL);
  return readWindow(page);
}

/** Картинка заполняет окно: object-fit cover по центру (50% 50%), элемент = окну ±1 px → полос нет (#d31f3b). */
export function expectCovered(s: Shot, label: string) {
  const img = s.img!;
  expect(img.fit, `${label}: object-fit`).toBe('cover');
  expect(img.pos, `${label}: object-position (по центру)`).toBe('50% 50%');
  expect(Math.abs(img.w - s.win.w), `${label}: ширина картинки ${img.w.toFixed(1)} = окну ${s.win.w.toFixed(1)}`).toBeLessThanOrEqual(PX_TOL);
  expect(Math.abs(img.h - s.win.h), `${label}: высота картинки ${img.h.toFixed(1)} = окну ${s.win.h.toFixed(1)}`).toBeLessThanOrEqual(PX_TOL);
}

/**
 * Окно фиксированного размера (#d31f3b): десктоп 800×400 (±2 px); телефон — 16:9 (±2 %) во всю ширину контента,
 * ниже 400 px. Не зависит от пропорции картинки.
 */
export function expectFixedFrame(s: Shot, dev: string, label: string) {
  const size = `${s.win.w.toFixed(1)}×${s.win.h.toFixed(1)}`;
  if (dev === '@desktop') {
    expect(Math.abs(s.win.w - DESKTOP_FRAME.w), `${label}: ширина окна ${size} ≈ ${DESKTOP_FRAME.w}`).toBeLessThanOrEqual(SIZE_TOL);
    expect(Math.abs(s.win.h - DESKTOP_FRAME.h), `${label}: высота окна ${size} ≈ ${DESKTOP_FRAME.h}`).toBeLessThanOrEqual(SIZE_TOL);
  } else {
    expect(Math.abs(s.win.w / s.win.h - 16 / 9) / (16 / 9), `${label}: окно ${size} — 16:9 ±2 %`).toBeLessThanOrEqual(RATIO_TOL);
    expect(s.win.h, `${label}: высота окна ${size} < 400`).toBeLessThan(400);
  }
}

/** Стрелка «המדיה הבאה». На iPhone прозрачная до тапа — для Playwright это видимый элемент, нажимается. */
export const nextArrow = (page: Page) => page.getByRole('button', { name: 'המדיה הבאה' }).first();

/** Стрелка «המדיה הקודמת». */
export const prevArrow = (page: Page) => page.getByRole('button', { name: 'המדיה הקודמת' }).first();

// ───────────────────────── #a6abaf: нет пустого/серого окна при смене картинки ─────────────────────────

/** Задержка ответов картинок supabase storage (по умолчанию 1.2 с) — медленная сеть, как в сценарии QA #a6abaf. */
export const IMAGE_DELAY_MS = 1200;
export async function delayStorageImages(page: Page, ms = IMAGE_DELAY_MS) {
  await page.route(/supabase\.co\/storage\/v1\//, async (route) => {
    if (route.request().resourceType() === 'image') await new Promise((r) => setTimeout(r, ms));
    return route.fallback();
  });
}

/** Кадр rAF: покрытие окна видимой загруженной медиа (0..1), размер окна, текущая картинка, scrollY. */
export type Frame = { t: number; cov: number; w: number; h: number; cur: string; loaded: string[]; sy: number };
/** Порог «окно не пустое»: видимая загруженная картинка закрывает ≥ 50 % окна (с учётом object-fit: contain). */
export const MIN_COVERAGE = 0.5;

/**
 * Запустить покадровую выборку (requestAnimationFrame) в странице. Каждый кадр: для каждой прямой <img> окна, которая
 * complete, naturalWidth > 0 и opacity (своя × окна) > 0.05, считается нарисованный прямоугольник по object-fit
 * contain (центр) ∩ окно; покрытие = максимум по картинкам (видео с readyState ≥ 2 — по своему прямоугольнику).
 * Окна нет в DOM — покрытие 0 (это тоже пустой кадр).
 */
export async function startSampler(page: Page) {
  await page.evaluate((css) => {
    const w = window as any;
    w.__galFrames = [];
    w.__galRun = true;
    const t0 = performance.now();
    const op = (e: Element) => parseFloat(getComputedStyle(e).opacity);
    const tick = () => {
      if (!w.__galRun) return;
      const win = document.querySelector(css) as HTMLElement | null;
      const f = { t: Math.round(performance.now() - t0), cov: 0, w: 0, h: 0, cur: '', loaded: [] as string[], sy: window.scrollY };
      if (win) {
        const r = win.getBoundingClientRect();
        f.w = r.width;
        f.h = r.height;
        const winOp = op(win);
        let best = -1;
        const inter = (x: number, y: number, cw: number, ch: number) =>
          Math.max(0, Math.min(x + cw, r.right) - Math.max(x, r.left)) * Math.max(0, Math.min(y + ch, r.bottom) - Math.max(y, r.top));
        for (const img of win.querySelectorAll(':scope > img') as NodeListOf<HTMLImageElement>) {
          if (!img.complete || !img.naturalWidth) continue;
          const src = img.currentSrc || img.src;
          f.loaded.push(src);
          const o = op(img) * winOp;
          if (o <= 0.05 || getComputedStyle(img).visibility === 'hidden') continue;
          const b = img.getBoundingClientRect();
          const fit = getComputedStyle(img).objectFit;
          let cw = b.width, ch = b.height;
          if (fit === 'contain') {
            const k = Math.min(b.width / img.naturalWidth, b.height / img.naturalHeight);
            cw = img.naturalWidth * k;
            ch = img.naturalHeight * k;
          }
          const cov = r.width * r.height > 0 ? inter(b.left + (b.width - cw) / 2, b.top + (b.height - ch) / 2, cw, ch) / (r.width * r.height) : 0;
          f.cov = Math.max(f.cov, cov);
          if (o > best) { best = o; f.cur = src; }
        }
        const v = win.querySelector(':scope > video') as HTMLVideoElement | null;
        if (v && v.readyState >= 2 && op(v) * winOp > 0.05) {
          const b = v.getBoundingClientRect();
          f.cov = Math.max(f.cov, inter(b.left, b.top, b.width, b.height) / (r.width * r.height));
          if (!f.cur) f.cur = v.currentSrc || v.src;
        }
      }
      w.__galFrames.push(f);
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }, WINDOW_CSS);
}

/** Остановить выборку (дождавшись ещё `tail` кадров — досмотреть конец анимации) и вернуть кадры. */
export async function stopSampler(page: Page, tail = 10): Promise<Frame[]> {
  return page.evaluate(async (n) => {
    const w = window as any;
    for (let i = 0; i < n; i++) await new Promise((r) => requestAnimationFrame(() => r(null)));
    w.__galRun = false;
    return w.__galFrames as Frame[];
  }, tail);
}

const short = (src: string) => src.split('/').pop()?.split('?')[0].slice(0, 12) || '—';

/** Ни одного кадра без видимой загруженной картинки (покрытие ≥ 0.5). В сообщении — первые пустые кадры. */
export function expectNoEmptyFrames(frames: Frame[], label: string) {
  expect(frames.length, `${label}: выборка сняла кадры`).toBeGreaterThan(10);
  const empty = frames.filter((f) => f.cov < MIN_COVERAGE);
  const minCov = Math.min(...frames.map((f) => f.cov));
  test.info().annotations.push({ type: 'кадры', description: `${label}: ${frames.length} кадров за ${frames[frames.length - 1]?.t ?? 0} мс, мин. покрытие ${minCov.toFixed(2)}, пустых ${empty.length}` });
  const sample = empty.slice(0, 5).map((f) => `t=${f.t}мс cov=${f.cov.toFixed(2)} окно ${f.w.toFixed(0)}×${f.h.toFixed(0)} cur=${short(f.cur)}`);
  expect(empty.length, `${label}: кадров без видимой картинки ${empty.length} из ${frames.length} (длительность ~${empty.length ? empty[empty.length - 1].t - empty[0].t : 0} мс): ${sample.join('; ')}`).toBe(0);
}

/** Перейти стрелкой и дождаться новой картинки (src сменился, загружена, opacity 1, окно подстроилось). */
export async function flip(page: Page, dir: 'next' | 'prev', label: string, prevSrc: string): Promise<Shot> {
  await (dir === 'next' ? nextArrow(page) : prevArrow(page)).click();
  return settledImage(page, label, prevSrc);
}

/**
 * «Соседи не загружены» детерминированно: все картинки storage держатся (не отвечают), пока тест их не отпустит.
 * `allowWindowImage` — отпустить первую картинку окна (с задержкой `ms`); `releaseAll` — отпустить остальные
 * (каждая отвечает через `ms` после отпускания). Предзагрузка соседей не успевает до клика — по построению.
 */
export async function holdStorageImages(page: Page, ms = IMAGE_DELAY_MS) {
  const key = (u: string) => u.split('?')[0];
  const allowed = new Set<string>();
  const waiting = new Map<string, Array<() => void>>();
  let all = false;
  await page.route(/supabase\.co\/storage\/v1\//, async (route) => {
    const r = route.request();
    if (r.resourceType() === 'image' && !all && !allowed.has(key(r.url()))) {
      await new Promise<void>((res) => waiting.set(key(r.url()), [...(waiting.get(key(r.url())) || []), res]));
    }
    if (r.resourceType() === 'image') await new Promise((res) => setTimeout(res, ms));
    return route.fallback();
  });
  const free = (k: string) => { (waiting.get(k) || []).forEach((f) => f()); waiting.delete(k); };
  return {
    async allowWindowImage() {
      const img = windowLocator(page).locator(':scope > img').first();
      await expect(img, 'в окне галереи есть <img> с src').toHaveAttribute('src', /\S/, LOAD);
      const k = key((await img.getAttribute('src'))!);
      allowed.add(k);
      free(k);
    },
    releaseAll() {
      all = true;
      [...waiting.keys()].forEach(free);
    },
  };
}

// ───────────────────────── #d31f3b: лайтбокс (полноэкранный просмотр) ─────────────────────────

/** Кнопка-слой поверх картинки в окне галереи — открывает лайтбокс (на слайде с видео её нет). */
export const fullscreenButton = (page: Page) => windowLocator(page).getByRole('button', { name: 'הצגת התמונה במסך מלא' });
/** Лайтбокс: role=dialog (radix), fixed inset-0, чёрный фон. */
export const lightbox = (page: Page) => page.getByRole('dialog');
/** Счётчик «N/M» (aria-live) в лайтбоксе. */
export const lbCounter = (page: Page) => lightbox(page).locator('[aria-live]');
export const lbNext = (page: Page) => lightbox(page).getByRole('button', { name: 'התמונה הבאה' });
export const lbPrev = (page: Page) => lightbox(page).getByRole('button', { name: 'התמונה הקודמת' });
export const lbClose = (page: Page) => lightbox(page).getByRole('button', { name: 'סגירה' });

export type LbShot = {
  dlg: { x: number; y: number; w: number; h: number; bg: string };
  vw: number;
  vh: number;
  bodyOverflow: string;
  scrollY: number;
  /** Картинка текущего слайда (слайд, чей левый край в 0 ±2 px, — карусель embla, слайды по 100 % ширины). */
  img: { alt: string; fit: string; complete: boolean; nat: [number, number]; x: number; y: number; w: number; h: number } | null;
  videos: number;
};

/** Снимок лайтбокса: размер/фон диалога, текущая картинка, overflow body, scrollY. */
export async function readLightbox(page: Page): Promise<LbShot> {
  return lightbox(page).evaluate((d: HTMLElement) => {
    const r = d.getBoundingClientRect();
    const vw = window.innerWidth;
    const cur = ([...d.querySelectorAll('img')] as HTMLImageElement[]).find((i) => {
      const b = i.getBoundingClientRect();
      return b.width > 0 && Math.abs(b.left) <= 2 && b.right <= vw + 2;
    });
    const b = cur?.getBoundingClientRect();
    return {
      dlg: { x: r.left, y: r.top, w: r.width, h: r.height, bg: getComputedStyle(d).backgroundColor },
      vw,
      vh: window.innerHeight,
      bodyOverflow: getComputedStyle(document.body).overflow,
      scrollY: window.scrollY,
      img: cur && b
        ? { alt: cur.alt, fit: getComputedStyle(cur).objectFit, complete: cur.complete, nat: [cur.naturalWidth, cur.naturalHeight] as [number, number], x: b.left, y: b.top, w: b.width, h: b.height }
        : null,
      videos: d.querySelectorAll('video').length,
    };
  });
}

/** Открыть лайтбокс кликом по картинке в окне и дождаться счётчика. */
export async function openLightbox(page: Page) {
  await fullscreenButton(page).click();
  await expect(lbCounter(page), 'лайтбокс открылся, счётчик виден').toBeVisible(LOAD);
}

/**
 * Дождаться, что счётчик = `n/total`, и картинка этого слайда стоит ровно в экране (листание закончилось), загружена.
 * `altSuffix` — для объявлений без видео alt картинки оканчивается на « - N» (N = номер слайда).
 */
export async function settledLightbox(page: Page, n: number, total: number, label: string, altSuffix = true): Promise<LbShot> {
  await expect(lbCounter(page), `${label}: счётчик`).toHaveText(`${n}/${total}`, LOAD);
  await expect
    .poll(async () => {
      const s = await readLightbox(page);
      if (!s.img || !s.img.complete || !s.img.nat[0] || Math.abs(s.img.x) > 1) return 'листается/грузится';
      return altSuffix && !s.img.alt.endsWith(`- ${n}`) ? `на экране «${s.img.alt}»` : 'ok';
    }, { ...LOAD, message: `${label}: на экране загруженная картинка ${n}` })
    .toBe('ok');
  return readLightbox(page);
}

/** Лайтбокс на весь экран на чёрном, картинка — contain на весь экран (целиком, без обрезки). */
export function expectFullscreenContain(s: LbShot, label: string) {
  expect(s.dlg.bg, `${label}: фон лайтбокса чёрный`).toBe('rgb(0, 0, 0)');
  expect(Math.abs(s.dlg.x) + Math.abs(s.dlg.y), `${label}: лайтбокс от левого верхнего угла экрана`).toBeLessThanOrEqual(PX_TOL);
  expect(Math.abs(s.dlg.w - s.vw), `${label}: ширина лайтбокса ${s.dlg.w} = экрану ${s.vw}`).toBeLessThanOrEqual(PX_TOL);
  expect(Math.abs(s.dlg.h - s.vh), `${label}: высота лайтбокса ${s.dlg.h} = экрану ${s.vh}`).toBeLessThanOrEqual(PX_TOL);
  const img = s.img!;
  expect(img.fit, `${label}: object-fit картинки в лайтбоксе`).toBe('contain');
  // contain + элемент в пределах экрана → картинка видна целиком.
  expect(img.x >= -PX_TOL && img.y >= -PX_TOL && img.x + img.w <= s.vw + PX_TOL && img.y + img.h <= s.vh + PX_TOL, `${label}: картинка ${img.w}×${img.h} в пределах экрана ${s.vw}×${s.vh}`).toBe(true);
}

/** Свайп пальцем (Chromium, CDP touch) по центру экрана: from → to по X. Только для проекта android. */
export async function touchSwipe(page: Page, fromX: number, toX: number) {
  const cdp = await page.context().newCDPSession(page);
  const y = Math.round((page.viewportSize()?.height ?? 800) / 2);
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: fromX, y }] });
  for (let i = 1; i <= 8; i++) {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: fromX + ((toX - fromX) * i) / 8, y }] });
  }
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await cdp.detach();
}
